    my $fwd_base;
    my $rev_base;

    if ($template eq 'input') {
        # For circular input, we need to linearize it
        # Take a portion and create primers that create the desired overhangs
        $fwd_base = substr($seq, 0, 40);  # Start from beginning
        $rev_base = substr($seq, -40);    # From end (will be reverse complemented)
    } else {
        # For linear sequences, use start and end
