#!/usr/bin/perl
use strict;
use warnings;

# Parse sequences
my %seqs;
open(my $fh, '<', 'sequences.fasta') or die "Cannot open sequences.fasta: $!";
my $name; my $seq = '';
while (my $line = <$fh>) {
    chomp($line);
    if ($line =~ /^>(.+)$/) {
        $seqs{$name} = $seq if $name;
        $name = $1; $seq = '';
    } else {
        $seq .= $line;
    }
}
$seqs{$name} = $seq if $name;
close($fh);

# BsaI-HF v2 recognition: GGTCTC + 4bp overhang on each side
# Design overhangs for circular assembly: input -> egfp -> flag -> snap -> back to input
my %overhangs = (
    'input_fwd' => 'AAAT',   # Start overhang
    'input_rev' => 'GGCT',   # End overhang
    'egfp_fwd'  => 'GGCT',   # Must match input_rev
    'egfp_rev'  => 'TACT',
    'flag_fwd'  => 'TACT',   # Must match egfp_rev
    'flag_rev'  => 'CGTA',
    'snap_fwd'  => 'CGTA',   # Must match flag_rev
    'snap_rev'  => 'AAAT',   # Must match input_fwd (circular)
);

sub rc {
    my ($s) = @_;
    $s = reverse($s);
    $s =~ tr/ACGT/TGCA/;
    return $s;
}

sub calc_tm {
    my ($seq) = @_;
    # Extract just the annealing part for Tm calculation
    my $cmd = qq{echo "$seq" | oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 2>/dev/null};
    my $tm = `$cmd`;
    chomp($tm);
    return $tm eq '' ? 0 : $tm;
}

my @primers;

# For each sequence, design forward and reverse primers
foreach my $template ('input', 'egfp', 'flag', 'snap') {
    next unless exists $seqs{$template};
    my $full_seq = $seqs{$template};
    my $len = length($full_seq);

    # Design forward primer
    my $fwd_overhang = $overhangs{$template . '_fwd'};
    my $bsai_site = 'GGTCTC';

    # Try different lengths of annealing sequence
    my $fwd_primer;
    my $found_fwd = 0;

    for (my $alen = 15; $alen <= 45; $alen++) {
        my $anneal = substr($full_seq, 0, $alen);
        my $tm = calc_tm($anneal);

        if ($tm >= 58 && $tm <= 72) {
            $fwd_primer = $bsai_site . $fwd_overhang . $anneal;
            push @primers, {
                name => $template . '_fwd',
                seq => $fwd_primer,
                anneal => $anneal,
                tm => $tm,
                type => 'fwd'
            };
            $found_fwd = 1;
            last;
        }
    }

    # Design reverse primer
    my $rev_overhang = $overhangs{$template . '_rev'};
    my $rev_anneal_start = $len - 45;
    $rev_anneal_start = 0 if $rev_anneal_start < 0;

    my $found_rev = 0;
    for (my $alen = 15; $alen <= 45; $alen++) {
        my $start = $len - $alen;
        $start = 0 if $start < 0;
        my $anneal = substr($full_seq, $start, $alen);
        my $rc_anneal = rc($anneal);
        my $tm = calc_tm($rc_anneal);

        if ($tm >= 58 && $tm <= 72) {
            my $rev_primer = $bsai_site . rc($rev_overhang) . $rc_anneal;
            push @primers, {
                name => $template . '_rev',
                seq => $rev_primer,
                anneal => $rc_anneal,
                tm => $tm,
                type => 'rev'
            };
            $found_rev = 1;
            last;
        }
    }
}

# Group by template and check Tm difference
my %primer_pairs;
foreach my $p (@primers) {
    my $template = $p->{name};
    $template =~ s/_(fwd|rev)$//;
    $primer_pairs{$template} = [] unless exists $primer_pairs{$template};
    push @{$primer_pairs{$template}}, $p;
}

# Output primers
open(my $out, '>', 'primers.fasta') or die "Cannot write primers.fasta: $!";
foreach my $template (sort keys %primer_pairs) {
    my @pair = @{$primer_pairs{$template}};
    if (@pair == 2) {
        my $tm_diff = abs($pair[0]->{tm} - $pair[1]->{tm});
        if ($tm_diff <= 5) {
            foreach my $p (@pair) {
                print $out ">" . $p->{name} . "\n";
                print $out $p->{seq} . "\n";
            }
        }
    }
}
close($out);

print "Primers designed and written to primers.fasta\n";
