my $blank_count = 0;
foreach my $line (@lines) {
    if ($line =~ /^\s*$/) {
        $blank_count++;
    }
}

if ($blank_count > 0) {
    print "ERROR: Found $blank_count blank lines in primers.fasta\n";
    exit 1;
}

# Parse primers
my %primers;
my $name; my $seq = '';
foreach my $line (@lines) {
    chomp($line);
    next if $line eq '';
    if ($line =~ /^>(.+)$/) {
        $primers{$name} = $seq if $name;
        $name = $1;
        $seq = '';
    } else {
        $seq .= $line;
    }
}
$primers{$name} = $seq if $name;

# Verify all required pairs exist
my @templates = qw(input egfp flag snap);
my $pairs_found = 0;
foreach my $t (@templates) {
    if (exists $primers{$t . '_fwd'} && exists $primers{$t . '_rev'}) {
        $pairs_found++;
        my $fwd_seq = $primers{$t . '_fwd'};
        my $rev_seq = $primers{$t . '_rev'};

        # Extract annealing lengths
        if ($fwd_seq =~ /^GGTCTC.{4}(.+)$/) {
            my $fwd_anneal = $1;
            my $fwd_len = length($fwd_anneal);
            if ($fwd_len < 15 || $fwd_len > 45) {
                print "ERROR: $t fwd annealing length $fwd_len not in [15,45]\n";
                exit 1;
            }
        }
        if ($rev_seq =~ /^GGTCTC.{4}(.+)$/) {
            my $rev_anneal = $1;
            my $rev_len = length($rev_anneal);
            if ($rev_len < 15 || $rev_len > 45) {
                print "ERROR: $t rev annealing length $rev_len not in [15,45]\n";
                exit 1;
            }
        }
    } else {
        print "ERROR: Missing $t fwd or rev\n";
        exit 1;
    }
}

if ($pairs_found == 4) {
    print "SUCCESS: All 4 primer pairs present and valid\n";
    print "File: primers.fasta\n";
    print "Pairs: $pairs_found\n";
    print "No blank lines: YES\n";
    exit 0;
} else {
    print "ERROR: Only $pairs_found pairs found, need 4\n";
    exit 1;
}
