#!/usr/bin/perl
use strict;
use warnings;

# Extract annealing regions from primers and verify Tm values
open(my $fh, '<', 'primers.fasta') or die "Cannot open primers.fasta: $!";
my $name; my $seq = '';
my %primers;
while (my $line = <$fh>) {
    chomp($line);
    next if $line eq '';
    if ($line =~ /^>(.+)$/) {
        $primers{$name} = $seq if $name;
        $name = $1;
        $seq = '';
    } else {
        $seq .= $line;
    }
}
$primers{$name} = $seq if $name;
close($fh);

print "Verifying Tm values for annealing regions:\n";

my %templates = (
    'input' => ['input_fwd', 'input_rev'],
    'egfp' => ['egfp_fwd', 'egfp_rev'],
    'flag' => ['flag_fwd', 'flag_rev'],
    'snap' => ['snap_fwd', 'snap_rev']
);

foreach my $template (sort keys %templates) {
    my @pair = @{$templates{$template}};
    my ($fwd_name, $rev_name) = @pair;

    my $fwd_seq = $primers{$fwd_name};
    my $rev_seq = $primers{$rev_name};

    my ($fwd_anneal, $rev_anneal);
    if ($fwd_seq =~ /^GGTCTC.{4}(.+)$/) {
        $fwd_anneal = $1;
    }
    if ($rev_seq =~ /^GGTCTC.{4}(.+)$/) {
        $rev_anneal = $1;
    }

    my $fwd_tm = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $fwd_anneal 2>/dev/null`;
    my $rev_tm = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $rev_anneal 2>/dev/null`;
    chomp($fwd_tm); chomp($rev_tm);

    my $diff = abs($fwd_tm - $rev_tm);
    my $fwd_ok = ($fwd_tm >= 58 && $fwd_tm <= 72) ? 'OK' : 'FAIL';
    my $rev_ok = ($rev_tm >= 58 && $rev_tm <= 72) ? 'OK' : 'FAIL';
    my $diff_ok = ($diff <= 5) ? 'OK' : 'FAIL';

    print "$template: Fwd Tm=$fwd_tm [$fwd_ok] Rev Tm=$rev_tm [$rev_ok] Diff=$diff [$diff_ok]\n";
}
